from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        # book_id -> user currently holding it
        self._borrowed = {}
        # (user, book_id) -> borrow day
        self._loan_dates = {}
        # user -> unpaid fines
        self._fines = {}

    def add_book(self, book_id: str) -> None:
        # Idempotent: adding an existing book is fine.
        if book_id not in self._borrowed:
            self._borrowed[book_id] = None

    def borrow(self, user: str, book_id: str, day: date) -> None:
        holder = self._borrowed.get(book_id)
        if holder is not None:
            raise ValueError(f"Book {book_id!r} is currently borrowed.")
        # A user may hold at most one book at a time.
        for b, u in self._borrowed.items():
            if u == user:
                raise ValueError(
                    f"User {user!r} already holds book {b!r}."
                )
        self._borrowed[book_id] = user
        self._loan_dates[(user, book_id)] = day

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if self._borrowed.get(book_id) != user:
            raise ValueError(
                f"User {user!r} has not borrowed book {book_id!r}."
            )
        borrow_day = self._loan_dates.pop((user, book_id))
        self._borrowed[book_id] = None

        due_day = borrow_day + timedelta(days=self.loan_days)
        fine = 0.0
        if day > due_day:
            delay_days = 0
            d = due_day + timedelta(days=1)
            while d <= day:
                if d.weekday() < 5:  # Mon-Fri
                    delay_days += 1
                d += timedelta(days=1)
            fine = delay_days * self.daily_fine

        if fine > 0:
            self._fines[user] = self._fines.get(user, 0.0) + fine
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self._fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self._fines.pop(user, None)
